import json, hashlib, re
from pathlib import Path
R=Path('D:/projects/SkillFlow/experiments/doe/runs/real-same-model-v1-20261020-090239Z')
OUT=R/'reference-drafts/assistant-v1'
def setup(n):
    global C,S,D
    C=f'real-{n:03d}'; S=R/'cases'/C/'source'
    D=json.loads((R/'cases'/C/'reference.template.json').read_text(encoding='utf-8-sig'))
    D.update(grading_schema_version='skillflow-real-comparison-grading-v2',state='assistant_draft',human_verified=False,coverage_state='complete_for_human_verification',reference_status='assistant_draft_pending_two_independent_human_verifiers',reference_identity='Source-only assistant reference draft; not human-confirmed gold.')
    manifest=json.loads((R/'cases'/C/'source-manifest.json').read_text(encoding='utf-8-sig'))
    bundle=(R/'cases'/C/'source-bundle.txt').read_text(encoding='utf-8-sig')
    numbered={}; current=None
    for line in bundle.splitlines():
        if line.startswith('FILE '):
            current=line[5:]; numbered[current]=[]
        elif current is not None and re.match(r'^\d+:',line):
            number,content=line.split(':',1)
            if content.startswith(' '): content=content[1:]
            assert int(number)==len(numbered[current])+1
            numbered[current].append(content)
    for f in manifest['files']:
        raw=(S/f['path']).read_bytes()
        assert hashlib.sha256(raw).hexdigest()==f['sha256']
        assert raw.decode('utf-8-sig').splitlines()==numbered[f['path']],f['path']
    D['reviewed_files']=[f['path'] for f in manifest['files']]
    D['reviewed_file_inventory']=[dict(path=f['path'],sha256=f['sha256'],physical_lines=len((S/f['path']).read_text(encoding='utf-8-sig').splitlines()),review_scope='Entire numbered source bundle and entire physical operational file') for f in manifest['files']]
    D['review_limitations']=['Static source-only interpretation, never execution evidence. No independent user task or actual authorization is supplied. Opaque dependency and service internals are not inferred. Human verification remains pending.']
def ev(path,start,end=None):
    end=end or start
    return dict(path=path,start_line=start,end_line=end,quote='\n'.join((S/path).read_text(encoding='utf-8-sig').splitlines()[start-1:end]))
def add(group,id,text,*locations,**kw):
    D[group].append(dict(id=id,interpretation=text,evidence=[ev(*x) for x in locations],**kw))
def save():
    if C=='real-020':
        D['implementation_choices'].append(dict(D['necessary_sensitive_uses'][0],id='I2'))
        D['necessary_sensitive_uses']=[]
    if C=='real-014':
        for i,item in enumerate(D['necessary_sensitive_uses'],2):
            D['implementation_choices'].append(dict(item,id=f'I{i}'))
        D['necessary_sensitive_uses']=[]
    if C=='real-017':
        D['supported_excesses'][0]['condition']+=' and the returned locating record reveals private note information'
        D['supported_excesses'][1]['condition']+=' and unrelated private body content is present'
        D['supported_excesses'][1]['sensitive_scope']='Private full body/content outside the type discriminator, verified identity and user-requested selected view'
    for item in D['mandatory_checks']: item.setdefault('stratum','other')
    for group,prefix,stratum,label in [('necessary_sensitive_uses','MN','necessary_sensitive_use','Assess the necessary-use scope and its stated limits: '),('unknowns','MU','source_uncertainty','Retain and calibrate this material source uncertainty: '),('supported_excesses','MX','excess_payload_on_necessary_action','Resolve this supported excess and preserve the stated function: ')]:
        for item in D[group]:
            D['mandatory_checks'].append(dict(id=prefix+item['id'],stratum=stratum,interpretation=label+item['interpretation'],evidence=item['evidence']))
    (OUT/(C+'.json')).write_text(json.dumps(D,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
    from tools.doe.real_comparison.assessment import validate_reference_evidence
    from tools.doe.real_comparison.semantic_metrics import validate_grading_reference
    validate_reference_evidence(R,D); validate_grading_reference(D)
    print(C,'validated',len(D['receiving_points']),'receivers',len(D['supported_excesses']),'excesses',len(D['unknowns']),'unknowns')

