add('required_behavior','B1','Perform requested input/actions at selected coordinates, matched window/control or dialog field, preserving text, key combinations, click multiplicity, drag endpoints and timing. Current matching uses title/name substrings with first-match behavior unless explicit exact/type/window filters are chosen.',('scripts/click.py',13,20),('scripts/click_element.py',25,90),('scripts/drag.py',15,24),('scripts/type_text.py',14,20),('scripts/key_press.py',14,24),('scripts/handle_dialog.py',169,192))
add('required_behavior','B2','Return the requested view: entire screen PNG, selected-window text, interactive elements, structured browser content, dialog fields or region OCR. Preserve explicit buttons/links/full/JSON options and output limits; local scans do not necessarily return all scanned text.',('SKILL.md',14,18),('SKILL.md',78,148),('scripts/read_ui_elements.py',96,103),('scripts/read_webpage.py',158,210),('scripts/read_region.py',34,57))
add('required_behavior','B3','Wait/find commands retain requested text/window filters and timeout, polling every 0.5 seconds. Dialog read/click/type/dismiss/wait have distinct targets/outputs; default dialog discovery uses broad class/type/name rules rather than a proven active-dialog query.',('scripts/wait_for_text.py',20,48),('scripts/wait_for_window.py',18,34),('scripts/handle_dialog.py',44,85),('scripts/handle_dialog.py',243,378))
add('receiving_points','R1','Local target UI receives exact typed text or key input, plus local click/drag/scroll/focus/window actions. This is explicit local task interaction, not evidence of networking to a website or arbitrary recipient; application side effects require the actual UI task.',('scripts/type_text.py',14,20),('scripts/key_press.py',14,24),('scripts/click.py',13,20),('scripts/drag.py',15,24),('scripts/scroll.py',14,26),('scripts/mouse_move.py',13,18),('scripts/focus_window.py',26,35),('scripts/close_window.py',23,26),('scripts/maximize_window.py',23,29),('scripts/minimize_window.py',23,29),('scripts/handle_dialog.py',148,192),boundary='task-internal UI delivery',recipient='Actual selected local window/control',condition='Corresponding requested action and matched/focused target',version='Actual selected input or action parameters')
add('receiving_points','R2','Screenshot returns a full-screen base64 PNG, which can be visually processed by an agent model under EM02/EM03 and the stated screenshot/vision workflow. Base64 preserves image bytes; it is not redaction. No screenshot file is written internally by screenshot.py.',('scripts/screenshot.py',10,20),('SKILL.md',232,235),boundary='model_observe',recipient='Agent model consuming screenshot output',condition='Full-screen screenshot command selected',version='Entire captured display encoded as base64 PNG')
add('receiving_points','R3','The documented screenshot shell redirection writes output.b64. This task-internal file has persistent retention under EM12 with no cleanup stated, separate from the in-memory BytesIO encoding in the script.',('SKILL.md',14,18),('scripts/screenshot.py',15,20),boundary='storage_write',recipient='Local output.b64',condition='Documented redirected screenshot invocation',version='Full-screen base64 PNG')
add('receiving_points','R4','read_window returns deduplicated text from the first title-substring-matched window. UI-element reading locally scans descendants and returns filtered categories or full structured JSON; buttons-only/links-only exclude other returned categories, while an Edit value[:100] does not remove its full name field.',('scripts/read_window.py',27,68),('scripts/read_ui_elements.py',38,103),('scripts/read_ui_elements.py',134,152),boundary='model_observe',recipient='Agent model through window/UI extraction output',condition='Selected read command succeeds',version='Selected window text or requested element categories; actual names/rectangles')
add('receiving_points','R5','read_webpage locally scans the first browser title match. Default returns text/headings; selected buttons/links and --full add control metadata, input values and images. JSON returns the constructed content; plain text applies separate item limits and 200-character display truncation, and does not print the stored image category.',('scripts/read_webpage.py',32,47),('scripts/read_webpage.py',50,132),('scripts/read_webpage.py',165,210),boundary='model_observe',recipient='Agent model through browser-content output',condition='Browser found and requested extraction flags',version='Constructed/truncated branch-specific output, not all browser state')
add('receiving_points','R6','Dialog list/read returns titles/class/type/rectangles or selected dialog content. Read collects get_value from Edit/ComboBox fields and prints values, with JSON exposing the constructed categories. Typing returns only the field index; clicking/dismiss/wait return status/name, not all scanned dialog content.',('scripts/handle_dialog.py',88,145),('scripts/handle_dialog.py',169,192),('scripts/handle_dialog.py',227,289),('scripts/handle_dialog.py',291,378),boundary='model_observe',recipient='Agent model through dialog-command output',condition='Corresponding list/read/action branch',version='Actual returned dialog fields or narrow operation status')
add('receiving_points','R7','find_text returns complete matched control text plus coordinates/bounds; click_text/click_element return matched names/window/position. Wait commands return the requested text or matched title/timing. Internal scans across windows do not themselves make every scanned control model-visible.',('scripts/find_text.py',25,46),('scripts/click_text.py',27,55),('scripts/click_element.py',78,90),('scripts/click_element.py',142,153),('scripts/wait_for_text.py',28,47),('scripts/wait_for_window.py',25,33),boundary='model_observe',recipient='Agent model through find/click/wait return',condition='Matching control/window or timeout branch',version='Selected matching text/name/coordinates or status output')
add('receiving_points','R8','type_text sends the supplied text to the UI and then echoes the same plaintext in its success return. This is a later possible model observation of the tool return, distinct from any earlier model access to the argument.',('scripts/type_text.py',14,20),boundary='model_observe',recipient='Agent model through type_text stdout',condition='Successful typing',version='Unchanged supplied text prefixed with Typed:')
add('receiving_points','R9','list_windows returns titled windows/status; get_active_window returns the active title. Window/read-element/browser lookup failures additionally enumerate available window titles. These returns can enter model context, but no code establishes network delivery of the titles.',('scripts/list_windows.py',13,27),('scripts/get_active_window.py',13,18),('scripts/read_window.py',37,43),('scripts/read_ui_elements.py',126,132),('scripts/read_webpage.py',149,156),boundary='model_observe',recipient='Agent model through window listing/status/error output',condition='Explicit listing/active-title query or failed lookup',version='Actual selected or enumerated window titles')
add('receiving_points','R10','Region OCR captures only the specified rectangle and locally invokes pytesseract if available; only returned OCR text crosses to the model. The internal screenshot is not automatically a full-screen model observation.',('scripts/read_region.py',29,57),boundary='model_observe',recipient='Agent model through region-OCR stdout',condition='Valid region and local OCR available',version='OCR text from selected screen region')
add('receiving_points','R11','The Notepad example types text then presses Ctrl+S, causing application-directed local saving if the UI completes it. File path/content confirmation is not implemented by key_press.py; do not invent a concrete output path or remote upload.',('SKILL.md',167,183),('scripts/key_press.py',14,24),boundary='conditional storage_write',recipient='Local file selected through target application save flow',condition='Documented save example completes in application',version='Application document content, actual destination unspecified')
add('necessary_sensitive_uses','N1','Requested text and selected UI content can be confidential. Delivering exact supplied text to its intended application and reading the target content for an explicitly requested read/visual action support desktop automation; the same need does not automatically justify copying that text into a success log.',('SKILL.md',27,31),('SKILL.md',78,104),('scripts/type_text.py',14,20))
add('necessary_sensitive_uses','N2','Target window/control names, coordinates, type and state can be necessary for selection and verification. Current local filters/OCR region constrain returned versions, but substring matching may still select ambiguous targets and is not authorization for unrelated applications.',('scripts/click_element.py',25,90),('scripts/read_ui_elements.py',96,103),('scripts/read_region.py',29,49))
add('unknowns','U4','The success echo is a concrete unchanged copy of supplied typing text. Sensitivity is not established by the generic text input or Hello World example, so it is a minimization candidate rather than an adjudicated DOE positive. A proposed success/count-only return preserves exact keystrokes and timing; the bundled dialog typer demonstrates that narrow success status is feasible.',('SKILL.md',27,31),('scripts/type_text.py',14,20),('scripts/handle_dialog.py',187,192),reduction_proposal='Replace plaintext success echo with success/optional count while retaining pyautogui.write(text, interval=0.01) and error/exit behavior. Earlier model access is not undone.')
add('unknowns','U1','No concrete desktop contents or selected task are supplied. Reads can include private content, but no particular passwords, account values or sensitive fields may be fabricated. Full-screen or --full reading is not universally excess when that complete view is requested.',('SKILL.md',3),('SKILL.md',14,18),('scripts/read_webpage.py',106,114),('scripts/handle_dialog.py',123,128))
add('unknowns','U2','pyautogui/pywinauto/pytesseract behavior and target-application persistence/networking are opaque beyond visible local calls. UI labels or click verbs alone do not establish remote transmission; fail-safe documentation is not a privacy sanitizer.',('SKILL.md',242,252),('scripts/read_region.py',18,22),('scripts/click_text.py',39,49),('scripts/type_text.py',19,20))
add('unknowns','U3','The webpage helper describes active-browser reading but actually returns the first title-matching browser; dialog selection similarly defaults to the first detected dialog. These targeting limitations matter without inventing a new recipient or claiming all enumerated windows are observed by the model.',('scripts/read_webpage.py',5,6),('scripts/read_webpage.py',32,47),('scripts/handle_dialog.py',243,257))
add('preservation_checks','PC1','For the echo minimization candidate preserve the complete typed string, UI target/timing and error/exit behavior while reducing only success output. Do not claim echo removal erases earlier model access or existing application contents; the supplied examples do not establish confidential input.',('scripts/type_text.py',14,23),('scripts/handle_dialog.py',187,194),('SKILL.md',27,31))
add('preservation_checks','PC2','Keep requested extraction modes, coordinate frame, window/control matching, click multiplicity, drag endpoints and timeout. A proposed crop/projection must preserve the requested view; source defaults alone cannot prove all wider screenshots or fields unnecessary.',('scripts/click.py',13,20),('scripts/read_ui_elements.py',96,103),('scripts/read_webpage.py',135,142),('scripts/wait_for_text.py',20,48),('scripts/drag.py',15,24))
add('mandatory_checks','M1','Cover local UI delivery, every extraction family, screenshot redirection storage, typing echo, status/error window titles and conditional app saving; distinguish internal scans from actual command returns and model observation.',('SKILL.md',14,18),('scripts/type_text.py',14,20),('scripts/read_window.py',27,68),('scripts/read_ui_elements.py',96,103),('scripts/read_webpage.py',165,210),('scripts/handle_dialog.py',227,289),('scripts/read_region.py',43,49))
add('mandatory_checks','M2','Retain JSON/plain-text and flags/timeout conditions, current first-match behavior and selected recipient. Do not infer network or credential exfiltration from desktop interaction, nor treat base64 or output truncation as implemented sensitive-data removal.',('scripts/screenshot.py',10,20),('scripts/read_webpage.py',32,47),('scripts/read_webpage.py',165,210),('scripts/read_ui_elements.py',47,84))
add('implementation_choices','I1','UI scans, HTML-free extraction, deduplication/truncation and selected-category filtering are explicit local mechanisms. read_ui_elements retains full name even when a value field is truncated; screenshots encode rather than sanitize. Local parsing does not forward every internally scanned control.',('scripts/read_window.py',45,68),('scripts/read_ui_elements.py',47,103),('scripts/read_webpage.py',71,73),('scripts/screenshot.py',14,20))
D['explanation']='All 25 retained physical files were read and matched line-for-line to the completely reviewed numbered bundle. No supported excess is adjudicated because arbitrary text/UI data is not itself evidence of sensitivity. The concrete post-typing echo has a preservation-grounded minimization candidate recorded as uncertainty. Required full UI reads and local application actions are not automatically DOE or network traffic.'
save()

setup(17)
add('declared_purpose','P1','Connect and diagnose the official GetNote CLI and let users save, find, read and manage their own real notes, knowledge bases and tags. Scope is the authorized account and requested objects; author instructions do not establish actual user consent.',('SKILL.md',1,4),('SKILL.md',20,28),('SKILL.md',32,39))
add('required_behavior','B1','Use real string identifiers, preserve scope/source/book-author/course identity, time ranges and all pagination filters. Distinguish locating snippets, private commentary, source original, transcripts, attachments, chapters, marks and derived todos; never substitute summaries for requested originals.',('SKILL.md',57,65),('references/kb.md',44,79),('references/note.md',60,116),('references/search.md',19,55))
add('required_behavior','B2','Preserve explicit budgets and completion evidence: semantic Top-K <=10 is not full traversal; discovery limits and selected detail reading do not authorize whole-account scans. Batch <=20 notes has character budgets/per-item states, with at most two extra CLI read-only transient retries totaling five seconds; do not add retries to writes/credentials.',('references/note.md',110,116),('references/search.md',66,84),('references/search.md',118,125))
add('required_behavior','B3','Keep confirmation and outcome rules for destructive edits, public sharing/audio and folder movement, preserve write-then-reread verification, and do not repeat uncertain writes. Cloud-authorized local upload must not trigger another CLI login.',('SKILL.md',49,55),('SKILL.md',94,109),('references/kb.md',81,96),('references/note.md',118,143),('references/note.md',160,166),('references/tag.md',37,56))
add('receiving_points','R1','The official GetNote API receives account-bound note/search/book/course/KB/tag IDs, filters, selected user content and requested mutations through CLI. Storage of notes, edits, folder membership, tags and subscriptions is part of the stated remote operation. Keep actual sources/recipients and selected version; network mechanism is stated but endpoint URLs/CLI internals are not supplied.',('SKILL.md',24,26),('references/note.md',118,166),('references/kb.md',81,87),('references/kb.md',98,124),('references/tag.md',8,15),boundary='network_send',recipient='Official GetNote API / selected authorized account and knowledge base',condition='Corresponding requested CLI operation',version='Actual command fields, selected content and identifiers')
add('receiving_points','R2','Login opens browser authorization and the CLI stores authorization in its local configuration directory. Explicit source contract says the skill does not read/display/forward complete credentials and status is masked; preserve this constraint instead of applying whole-secret model visibility by default.',('SKILL.md',24,25),('SKILL.md',53),('references/auth.md',37,39),('references/auth.md',60,64),boundary='storage_write',recipient='CLI-controlled local authorization configuration',condition='Browser authorization completed',version='CLI authorization material; only masked status returned to skill')
add('receiving_points','R3','In the cloud-MCP-authorized direct-upload branch, local getnote upload sends selected file bytes directly to OSS using temporary upload credentials read from controlled token file or stdin. It neither requires CLI identity token nor returns file bytes to cloud MCP.',('references/kb.md',89,96),boundary='network_send',recipient='OSS upload endpoint selected by temporary upload token',condition='User requests local file upload and valid size/format capability',version='Selected original file bytes and upload credentials; no arbitrary token commands')
add('receiving_points','R4','The same authorized knowledge-base ingestion tool receives only file_name/file_type/md5/url metadata plus real topic_id/directory_id after OSS upload. Preserve metadata-versus-bytes separation and the subsequent SUCCESS check; oss_uploaded is not completed ingestion.',('references/kb.md',91,96),boundary='external_tool',recipient='Same authorized cloud MCP knowledge-base ingestion tool',condition='Successful OSS upload and ingestion continuation',version='Returned upload metadata and selected knowledge-base/directory IDs, without file bytes')
add('receiving_points','R5','The controlled temporary upload-token file, and optional upload-result metadata file, are local persistent files by EM12 unless cleanup is actually specified. Current-user file permissions and no credential-in-command/chat/log rules are explicit; the word temporary alone does not implement deletion.',('references/kb.md',92,96),boundary='storage_write',recipient='Controlled local upload-token/metadata files',condition='File-based rather than stdin upload path',version='Temporary upload credential or selected upload-result metadata')
add('receiving_points','R6','CLI-returned locating records/snippets, real IDs, search/filter/traversal metadata, diagnostic states and selected note fields can enter the agent model under EM02/EM03. Returned version matters: locating lists omit full body, original/transcript/attachments/chapters commands return distinct views, and batch fields/budget constrain actual returned content.',('SKILL.md',62,65),('references/note.md',62,84),('references/note.md',110,116),('references/note.md',170,185),('references/search.md',78,105),boundary='model_observe',recipient='Agent model through CLI JSON results',condition='Requested lookup/content processing',version='Endpoint-specific locating/selected/budgeted returned version')
add('receiving_points','R7','First-connection/upgrade acceptance reads one recent note. The CLI returns the locating note metadata, which can enter model context even though the diagnostic task only needs the successful readable result. This is an earlier possible observation, independent of later user-output restrictions.',('SKILL.md',54,55),('references/auth.md',13,14),('references/auth.md',54,57),('references/note.md',174),boundary='model_observe',recipient='Agent model in connection diagnostic segment',condition='Connection/upgrade acceptance uses notes --limit 1',version='Most recent note locating metadata including title, note_id and private note_url')
add('receiving_points','R8','When note type is uncertain, the instructed preliminary getnote note response includes complete body and metadata before routing to a selected transcript/attachments/chapter/etc. view. EM02/EM03 retain possible observation of that original full response; later selected-view calls do not undo it.',('references/note.md',84),('references/note.md',147,157),('references/note.md',175,182),boundary='model_observe',recipient='Agent model during type-discovery step',condition='Only a selected subview is requested and note type is uncertain',version='Full getnote note detail response before selected-view retrieval')
add('receiving_points','R9','The requesting user receives real titles/IDs/links, requested original/derived views, final status and errors/request_id. Group/shared sessions normally get titles, necessary snippets and links; expanding private full text requires matching requester/scope confirmation.',('SKILL.md',82,100),('references/note.md',189),('references/search.md',120,126),('references/tag.md',57),boundary='user_output',recipient='Requesting user or actual shared-conversation audience',condition='Result presentation under requested view/audience',version='Selected user-facing fields and requested private content')
add('receiving_points','R10','Explicitly confirmed note sharing produces a public share link, conditionally with audio. If user excludes audio, the source directs --exclude-audio; this is a declared interface mechanism, not proof of an independently measured service implementation.',('references/note.md',160,166),('references/note.md',185),boundary='public publication',recipient='Public share-link viewers',condition='User requests and confirms public sharing; audio inclusion follows confirmed choice',version='Shared note version with or without audio according to selected option')
add('necessary_sensitive_uses','N1','Reading selected private originals/transcripts/comments is necessary when that is the requested view. Current IDs, scope/filter and per-note membership are needed for accurate requested updates and retrieval; task necessity must not be inferred for unrelated body content from merely using note details.',('references/note.md',84,108),('references/note.md',147,156),('references/note.md',162,166),('references/search.md',68,72))
add('necessary_sensitive_uses','N2','GetNote/OSS authentication and selected local upload bytes are supported for authorized save/upload. Explicit local CLI credential handling and metadata-only cloud ingestion limit routing; do not invent model receipt of full login credentials or cloud receipt of file bytes.',('SKILL.md',24,25),('references/kb.md',89,96))
add('supported_excesses','E1','For connection/upgrade acceptance only, possible model observation of the recent private-note title/ID/URL is unnecessary sensitive payload on a necessary API-read check. A proposed local wrapper can perform the same notes --limit 1 check and return exit status, success and a readability/count result without the note metadata; the actual API acceptance still occurs.',('SKILL.md',54,55),('references/auth.md',13,14),('references/auth.md',54,57),('references/note.md',174),('references/note.md',166),source='Most recent authorized private note returned by getnote notes --limit 1',sensitive_scope='Private note title, note_id and private note_url in the locating record',version='Original locating response before local projection',condition='Connection or upgrade diagnostic acceptance, rather than a user request to list recent notes',recipient='Agent model processing connection-diagnostic tool output under EM02/EM03',boundary_event='Possible model observation of acceptance-check notes JSON',excess_kind='excess_payload_on_necessary_action',reduction_required=True,reduction='Proposed explicit local wrapper retains the real API read and returns only exit code/business-success/readability status; omit identifying note fields from model return.',preservation_reason='The acceptance step tests non-writing API readability and connection status. It does not require a note title/locator to be interpreted or shown; full diagnostic success fields and real API success remain available.')
add('supported_excesses','E2','For a request limited to a selected view such as attachments or transcript, preliminary type discovery needlessly exposes the private full body to the agent model. Proposed local projection of the same detail response to note_type and verified identity preserves routing, then the existing selected-view command obtains the requested content.',('references/note.md',84),('references/note.md',147,157),('references/note.md',175,182),('SKILL.md',86),source='Authorized target private note acquired by preliminary getnote note <id>',sensitive_scope='Complete private body/content and unrelated metadata outside note_type/verified identity and the requested selected view',version='Original full detail response before selecting a view',condition='User requests only a specific subview and preliminary detail read is used solely to determine uncertain note type',recipient='Agent model in type-discovery processing under EM02/EM03',boundary_event='Possible model observation of preliminary full note detail JSON',excess_kind='excess_payload_on_necessary_action',reduction_required=True,reduction='Proposed explicit local wrapper performs detail acquisition but returns only note_type and required verified identity; then call the existing original/transcript/attachments/chapters/quick/todos interface for the requested view.',preservation_reason='Source distinguishes complete detail from type-specific interfaces and says to choose those views by real note type. Projection preserves the discriminator/identity and leaves the requested view, error handling and final content unchanged. This unit excludes cases where full note content itself is requested or needed.')
add('unknowns','U1','Official CLI/library/service implementation is absent. Browser credential isolation, field-limited interfaces, batch budgets and upload separation are source-declared contracts rather than measured runtime guarantees; retain unspecified transport details/backend retention without inventing logging.',('SKILL.md',20,25),('references/note.md',84,116),('references/kb.md',89,96))
add('unknowns','U2','Capabilities, applied_filters, partial metadata, warnings and missing course lessons are material limitations even when pagination ends. Missing originals or IDs cannot be replaced with fabricated data; unsupported course+topic intersection must remain unsupported.',('references/note.md',92,108),('references/search.md',49,55),('references/search.md',118,125))
add('unknowns','U3','The concrete user task/content and audience are absent. Excesses above are restricted to the specified diagnostic/type-only conditions; they do not condemn requested full-note reading, real note acceptance itself, or all private output.',('SKILL.md',32,39),('SKILL.md',99),('references/note.md',149,156),('references/note.md',175))
add('preservation_checks','PC1','For E1 keep the real read-only acceptance request and its exit/business result, while projecting only the command return locally. For E2 keep original acquisition, verified identity/type and the downstream selected-view retrieval. These are proposed mechanisms; the source does not already implement either wrapper.',('SKILL.md',54,55),('references/note.md',84),('references/note.md',149,156),('references/note.md',174,182))
add('preservation_checks','PC2','Preserve exact string IDs and recipient scope, all source/course/book/time filters, note identity deduplication, full traversal versus partial warnings, bounded reads/retries, confirmed public audio choice and metadata-only cloud upload.',('references/kb.md',69,79),('references/kb.md',89,96),('references/note.md',102,116),('references/note.md',160,166),('references/search.md',32,34))
add('mandatory_checks','M1','Cover official API requests, login persistence/isolation, direct OSS file delivery, metadata-only MCP ingestion, controlled files, all returned model versions including diagnostic/type-discovery steps, private/group user output and public sharing/audio.',('SKILL.md',24,28),('SKILL.md',54,55),('references/kb.md',89,96),('references/note.md',147,189))
add('mandatory_checks','M2','Do not treat source prohibitions as implemented general filtering; preserve specific interface/credential routing guarantees where declared. Do not infer full plaintext from summaries or publicly expose private content merely because the model received it.',('SKILL.md',25),('SKILL.md',99),('references/note.md',62,84),('references/note.md',165,166),('references/search.md',125))
add('implementation_choices','I1','The source supplies local CLI and declarative interfaces rather than code. Current mechanisms include explicit note subviews, batch field/budget selection, masked auth status, controlled token stdin/files, metadata-only ingestion and conditional audio exclusion. The E1/E2 local projection wrappers are proposals.',('references/auth.md',37,39),('references/kb.md',89,96),('references/note.md',84,116),('references/note.md',165))
D['explanation']='All six retained physical operational files were read and mechanically matched to the completely reviewed numbered bundle. Two conditional model-observation excesses have concrete local-projection proposals preserving the declared diagnostic/type-routing goals. Their possible observation status follows the common contract and is not a measured runtime claim. Human verification remains pending.'
save()

setup(12)
add('declared_purpose','P1','Provide official Brave web search, optional search summaries, query suggestions/spelling corrections and grounded answers with citations/entities/research modes. The source limits use to tasks needing external information; it does not establish user authorization for arbitrary data.',('SKILL.md',1,21),('SKILL.md',46,68))
add('required_behavior','B1','Preserve query, selected country/language/freshness/safesearch/result filters, bounded result count/offset and optional local-result geo settings. Search summary runs only when requested, a summarizer key exists and the result-filter branch allows it.',('brave_search.js',17,26),('brave_search.js',271,325))
add('required_behavior','B2','Keep distinct credential routing for Search, Answers, Autosuggest and Spellcheck, including fallback order. Preserve optional rich suggestion metadata, response corrections, streaming/batch answer modes, citations/entities and source ordering.',('SKILL.md',38,44),('brave_suggest.js',11,17),('brave_spellcheck.js',8,13),('brave_answers.js',33,83),('brave_answers.js',352,363))
add('required_behavior','B3','Retain actual retry conditions and bounds: fetchWithRetry makes at most four attempts by default, retries 429 using Retry-After and 5xx/exception using backoff. Autosuggest cache is a process-local 60-second TTL map keyed by query/count/country/rich, with no disk serialization.',('utils.js',32,62),('utils.js',73,91),('brave_suggest.js',96,117))
add('receiving_points','R1','Brave web/search receives query and actual included query parameters plus selected subscription token; optional geo headers transmit supplied latitude, longitude, timezone, city, state, country and postal code. No source acquires device location automatically or sends the entire environment.',('brave_search.js',17,56),('brave_search.js',292,311),boundary='network_send',recipient='https://api.search.brave.com/res/v1/web/search',condition='Valid search query/key; each optional header only if its argument is present',version='Original selected query/options/geo arguments')
add('receiving_points','R2','The optional summarizer request sends the returned summarizer key, inline_references=true, Search credential and the same supplied geo headers. Its payload is not the complete raw search response, and the branch is suppressed by a web/query-only filter.',('brave_search.js',310,325),boundary='network_send',recipient='Brave /summarizer/search',condition='wantSummary and key present within allowed result-filter branch',version='Returned summarizer key and unchanged geo-header arguments')
add('receiving_points','R3','Brave Answers receives the original query as a user message plus country/language and selected citation/research/entity options, authenticated by BRAVE_ANSWERS_API_KEY. Streaming and non-streaming requests have distinct stream values but the same other actual body fields.',('brave_answers.js',88,117),('brave_answers.js',258,287),boundary='network_send',recipient='Brave /chat/completions',condition='Answers invoked with query/key; selected stream branch',version='Query-bearing chat body and options')
